  let openInfoKey = null;
  let starByIdCache = null;

  function getStarById(id){
    if(!starByIdCache){
      starByIdCache = {};
      if(global.ISSStars){
        global.ISSStars.STAR_CATALOG.forEach(s=>{ starByIdCache[s.id] = s; });
      }
    }
    return starByIdCache[id];
  }

  function normalizeAngle180(deg){
    let d = deg % 360;
    if(d > 180) d -= 360;
    if(d < -180) d += 360;
    return d;
  }

  // --- Smoothing adaptif (mirip semangat complementary filter) ---------------
  // Sebelumnya pakai konstanta smoothing tetap (0.28) - hasilnya trade-off
  // tunggal: kalau di-set responsif jadi jitter, kalau di-set halus jadi lag
  // pas HP digerakkan cepat. Di sini alpha dihitung per-frame dari kecepatan
  // sudut aktual (delta / dt): gerakan cepat -> alpha tinggi (percaya sensor,
  // biar gak lag/ketinggalan), HP relatif diam -> alpha rendah (redam noise
  // magnetometer biar marker gak "gemeteran"). Ini bukan complementary filter
  // penuh (yang idealnya fusi dengan integrasi gyroscope), tapi tanpa perlu
  // sensor tambahan sudah jauh mengurangi jitter vs konstanta tetap.
  const SMOOTH_ALPHA_MIN = 0.12;   // saat diam -> banyak diredam
  const SMOOTH_ALPHA_MAX = 0.85;   // saat gerak cepat -> nyaris raw, biar gak lag
  const SMOOTH_SLOW_DEG_S = 8;     // di bawah ini dianggap "diam"
  const SMOOTH_FAST_DEG_S = 90;    // di atas ini dianggap "gerak cepat"

  let lastHeadingSampleAt = null;

  function adaptiveAlpha(deltaDeg, dtMs){
    if(dtMs <= 0) return SMOOTH_ALPHA_MAX;
    const degPerSec = Math.abs(deltaDeg) / (dtMs / 1000);
    if(degPerSec <= SMOOTH_SLOW_DEG_S) return SMOOTH_ALPHA_MIN;
    if(degPerSec >= SMOOTH_FAST_DEG_S) return SMOOTH_ALPHA_MAX;
    const t = (degPerSec - SMOOTH_SLOW_DEG_S) / (SMOOTH_FAST_DEG_S - SMOOTH_SLOW_DEG_S);
    return SMOOTH_ALPHA_MIN + t * (SMOOTH_ALPHA_MAX - SMOOTH_ALPHA_MIN);
  }

  function smoothHeadingTowards(prev, target, dtMs){
    if(prev === null) return target;
    const delta = normalizeAngle180(target - prev);
    const alpha = adaptiveAlpha(delta, dtMs);
    return ((prev + alpha*delta) % 360 + 360) % 360;
  }

  function smoothPitchTowards(prev, target, dtMs){
    if(prev === null) return target;
    const alpha = adaptiveAlpha(target - prev, dtMs);
    return prev + alpha*(target - prev);
  }

