  // Pindah antara mode 'camera' (passthrough kamera HP, kayak biasa) dan
  // 'texture' (langit di-render di atas latar bintang tanpa kamera sama
  // sekali, kayak mode non-kamera Stellarium) - sensor arah HP tetap dipakai
  // di kedua mode, cuma latar belakangnya yang beda.
  async function toggleArDisplayMode(){
    if(arDisplayMode === 'camera'){
      arDisplayMode = 'texture';
      stopCamera();
      updateArModeBtnUI();
      saveDisplayModePref();
      // Biar dtMs gyro dihitung dari 0 lagi (bukan pakai timestamp basi
      // dari sesi texture sebelumnya) tiap kali masuk mode texture.
      lastGyroSampleAt = null;
      return;
    }
    // Balik ke mode kamera - kameranya sengaja dimatikan pas masuk mode
    // langit, jadi minta stream-nya lagi di sini.
    const ok = await requestCamera();
    if(ok){
      arDisplayMode = 'camera';
      if(noteEl) noteEl.textContent = '';
      saveDisplayModePref();
      // Roll cuma berlaku di mode texture (lihat catatan di deklarasi
      // deviceRoll) - reset ke null biar gak ada rotasi "nyangkut" pas
      // balik ke mode kamera, dan biar reading gyro berikutnya snap lagi
      // kalau balik ke mode texture.
      deviceRoll = null;
      lastGyroSampleAt = null;
    } else {
      // Gagal (ditolak/tidak ada kamera) - tetap di mode langit, kasih tau kenapa.
      if(noteEl) noteEl.textContent = window.I18N ? I18N.t('ar.cameraDenied') : 'Tidak bisa mengakses kamera. Menampilkan mode kompas saja.';
    }
    updateArModeBtnUI();
  }

